class TreeNode:
    """Simple binary tree node."""

    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right


def is_tree_balanced(root):
    """Return True if binary tree is height-balanced, else False.

    A tree is balanced if for every node the heights of its left and
    right subtrees differ by at most 1. An empty tree (None) is balanced.
    """

    def _height(node):
        if node is None:
            return 0
        if isinstance(node, dict):
            left = node.get("left")
            right = node.get("right")
        elif isinstance(node, (list, tuple)):
            if len(node) == 3:
                left = node[1]
                right = node[2]
            elif len(node) == 2:
                left = node[0]
                right = node[1]
            elif len(node) == 0:
                return 0
            else:
                return 1
        elif hasattr(node, "left") or hasattr(node, "right"):
            left = getattr(node, "left", None)
            right = getattr(node, "right", None)
        else:
            return 1
        left_h = _height(left)
        if left_h == -1:
            return -1
        right_h = _height(right)
        if right_h == -1:
            return -1
        if abs(left_h - right_h) > 1:
            return -1
        return max(left_h, right_h) + 1

    try:
        return _height(root) != -1
    except RecursionError:
        return False
